CREATE TABLE IF NOT EXISTS admin_users (id INTEGER PRIMARY KEY AUTOINCREMENT,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS medicament (id INTEGER PRIMARY KEY AUTOINCREMENT,nom VARCHAR(190) NOT NULL COLLATE NOCASE UNIQUE,quantite INTEGER NOT NULL DEFAULT 0 CHECK(quantite>=0),prix DECIMAL(12,2),is_actif INTEGER NOT NULL DEFAULT 1 CHECK(is_actif IN(0,1)));
CREATE TABLE IF NOT EXISTS client_users (id INTEGER PRIMARY KEY AUTOINCREMENT,nom VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,telephone VARCHAR(30),password VARCHAR(255) NOT NULL,google_id VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patient_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT,full_name VARCHAR(100) NOT NULL,phone VARCHAR(30),email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS patient_requests (id INTEGER PRIMARY KEY AUTOINCREMENT,access_token_hash VARCHAR(64) NOT NULL UNIQUE,request_type VARCHAR(30) NOT NULL,patient_id INTEGER REFERENCES patient_accounts(id),patient_name VARCHAR(100) NOT NULL,phone VARCHAR(30),email VARCHAR(190),status VARCHAR(30) NOT NULL,total_amount DECIMAL(12,2),payment_mode VARCHAR(30),payment_phone VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patient_request_items (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL REFERENCES patient_requests(id),medicament_id INTEGER NOT NULL REFERENCES medicament(id),medicament_name VARCHAR(190) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price DECIMAL(12,2),is_available INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pharmacy_settings (id INTEGER PRIMARY KEY,is_on_call INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_attempts (bucket VARCHAR(64) NOT NULL,window_id INTEGER NOT NULL,attempts INTEGER NOT NULL,PRIMARY KEY(bucket,window_id));
INSERT OR IGNORE INTO pharmacy_settings(id,is_on_call) VALUES(1,0);
CREATE TABLE IF NOT EXISTS reservations (id INTEGER PRIMARY KEY AUTOINCREMENT,reference VARCHAR(16) NOT NULL UNIQUE,client_id INTEGER NOT NULL REFERENCES client_users(id),medicament_id INTEGER NOT NULL REFERENCES medicament(id),medicament_name VARCHAR(190) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 100),phone VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN('pending','confirmed','collected','rejected','expired','cancelled')),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reservations_expiry ON reservations(status,expires_at);
CREATE INDEX IF NOT EXISTS reservations_client ON reservations(client_id,id);
CREATE TABLE IF NOT EXISTS guard_pharmacies (id INTEGER PRIMARY KEY AUTOINCREMENT,name VARCHAR(190) NOT NULL,address VARCHAR(255) NOT NULL,commune VARCHAR(100) NOT NULL,phone VARCHAR(30) NOT NULL,start_at BIGINT NOT NULL,end_at BIGINT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),is_olg INTEGER NOT NULL DEFAULT 0 CHECK(is_olg IN(0,1)),CHECK(end_at>start_at));
CREATE INDEX IF NOT EXISTS reservations_medicine ON reservations(medicament_id,status);

CREATE TABLE IF NOT EXISTS pharmacies (id INTEGER PRIMARY KEY AUTOINCREMENT,name VARCHAR(190) NOT NULL,address VARCHAR(255) NOT NULL,commune VARCHAR(100) NOT NULL,phone VARCHAR(30) NOT NULL,identity_key VARCHAR(64) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS pharmacy_guards (id INTEGER PRIMARY KEY AUTOINCREMENT,pharmacy_id INTEGER NOT NULL,start_at BIGINT NOT NULL,end_at BIGINT NOT NULL,cancelled INTEGER NOT NULL DEFAULT 0,legacy_id INTEGER UNIQUE, FOREIGN KEY(pharmacy_id) REFERENCES pharmacies(id),CHECK(end_at>start_at));
